import type { ComponentType } from 'react';
import type { CodeViewProps } from './svg-view';

/**
 * The code kinds (D-257): an SVG artifact (preview from a blob URL, or its source) and a CSV artifact (a table). Both draw inside the
 * panel's viewer bar, with its copy and download. This module is cheap; each view loads the first time its artifact opens. Other code
 * and text stay in the panel's own code block.
 */
export interface CodeKind {
  readonly match: (target: { readonly resource: { readonly path: string } }, artifact: { readonly type: string; readonly language?: string | undefined }) => boolean;
  readonly label?: string | undefined;
  /** A default viewer for a type: a host's `viewers.svg` or `viewers.code` wins over it. */
  readonly fallback: true;
  readonly load: () => Promise<{ readonly default: ComponentType<CodeViewProps> }>;
}

export const svgKind: CodeKind = {
  match: (_target, artifact) => artifact.type === 'svg',
  fallback: true,
  load: () => import('./svg-view').then(module => ({ default: module.SvgView })),
};

export const csvKind: CodeKind = {
  match: (_target, artifact) => artifact.type === 'code' && artifact.language === 'csv',
  fallback: true,
  load: () => import('./csv-table').then(module => ({ default: module.CsvView })),
};

'use client';

import { useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { CodeXmlIcon, EyeIcon } from 'lucide-react';
import { CodeBlock } from '../pi-chat/code-block';
import { ViewerToggle } from '../viewer-frame/viewer-frame';
import { useViewerText } from '../viewer-frame/viewer-window';

/** What the code kinds' views read of the panel's kind props (structurally `ArtifactKindViewProps` of pi-artifacts). */
export interface CodeViewProps {
  readonly text: string;
  readonly artifact: { readonly title: string };
  /** The panel bar's controls slot (the preview and source toggle goes there). */
  readonly setControls?: ((controls: ReactNode) => void) | undefined;
}

/** An SVG artifact: a preview, or its source. The preview is an image from a blob URL: it never becomes markup in this page, so its scripts cannot run. */
export function SvgView({ text, artifact, setControls }: CodeViewProps) {
  const { labels } = useViewerText();
  const [mode, setMode] = useState<'preview' | 'source'>('preview');
  const url = useMemo(() => URL.createObjectURL(new Blob([text], { type: 'image/svg+xml' })), [text]);
  useEffect(() => () => URL.revokeObjectURL(url), [url]);
  useEffect(() => {
    setControls?.(<ViewerToggle label={labels.view} value={mode} onChange={setMode} options={[
      { id: 'preview', label: labels.preview, text: labels.preview, icon: <EyeIcon className="size-4" aria-hidden="true" />, testId: 'artifact-mode' },
      { id: 'source', label: labels.source, text: labels.source, icon: <CodeXmlIcon className="size-4" aria-hidden="true" />, testId: 'artifact-mode' }]} />);
    return () => setControls?.(undefined);
  }, [setControls, mode, labels.view, labels.preview, labels.source]);
  return mode === 'preview'
    ? <div className="boring-viewer-checker flex h-full min-h-0 items-center justify-center overflow-auto p-6"><img data-testid="artifact-svg" src={url} alt={artifact.title} className="max-h-full max-w-full" /></div>
    : <div className="min-h-0 p-3"><CodeBlock code={text} language="svg" /></div>;
}

'use client';

import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import type { CodeViewProps } from './svg-view';

/** Rows of a CSV text (comma or semicolon separated, double-quoted cells with `""` escapes), at most 2000. */
export function csvRows(text: string): string[][] {
  const rows: string[][] = []; let row: string[] = [], cell = '', quoted = false;
  for (let i = 0; i < text.length && rows.length < 2000; i++) {
    const c = text[i];
    if (quoted) { if (c === '"' && text[i + 1] === '"') { cell += '"'; i++; } else if (c === '"') quoted = false; else cell += c; }
    else if (c === '"') quoted = true;
    else if (c === ',' || c === ';') { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(cell); rows.push(row); row = []; cell = ''; }
    else cell += c;
  }
  if ((cell || row.length) && rows.length < 2000) { row.push(cell); rows.push(row); }
  return rows;
}

/** A CSV artifact as a table: the first row is the header. */
export function CsvView({ text }: CodeViewProps) {
  const [head = [], ...rows] = csvRows(text);
  return <Table data-testid="artifact-csv">
    <TableHeader><TableRow>{head.map((cell, i) => <TableHead key={i}>{cell}</TableHead>)}</TableRow></TableHeader>
    <TableBody>{rows.map((row, i) => <TableRow key={i}>{row.map((cell, j) => <TableCell key={j} className="align-top">{cell}</TableCell>)}</TableRow>)}</TableBody>
  </Table>;
}
